$ cat Bench.java
public class Bench {
    public static void main(String[] a) {
        long t0 = System.nanoTime();
        List<byte[]> live = new ArrayList<>();
        Deque<byte[]> churn = new ArrayDeque<>();
        for (int i = 0; i < 1_200_000; i++) {
            churn.add(new byte[8 * 1024]);
            if (churn.size() > 2000) churn.poll();
            if (i % 60 == 0) live.add(new byte[8 * 1024]);
            if (live.size() > 30000) live.subList(0, 10000).clear();
        }
        System.out.printf("wall %,d ms  live=%d%n", (System.nanoTime()-t0)/1_000_000, live.size());
    }
}

$ for GC in UseSerialGC UseParallelGC UseG1GC; do
    java -XX:+$GC -Xmx1g -Xlog:gc -cp out Bench
  done

